snippet_css:
:root{
  --bg: #F2EDE4;
  --fg: #3B3A36;
  --muted: #635A4E;
  --surface: #E9E2D6;
  --border: #C9BFB0;
  --accent: #8A5636;
  --accent-fg: #FDFBF6;
  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 10px 26px rgba(59,58,54,.10);
  --btn-shadow: 0 2px 0 rgba(138,86,54,.35);
  --art-bg: radial-gradient(circle at 38% 32%,#E4DDD1,#A89A86 55%,#6F6353);
  --media-bg: radial-gradient(circle at 34% 30%,#E4DDD1,#C9BFB0);
  --cta-bg: #E9E2D6;
  --input-bg: #FBF8F2;
  --ok: #4E6B47;
  --warn: #8C3B2E;
  --font-display: Cormorant,'Noto Serif TC',serif;
  --font-body: 'Noto Sans TC',sans-serif;
  --font-mono: 'Cormorant',ui-monospace,serif;
  --focus-ring: var(--accent);
}

snippet_tailwind:
